module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W  = ADDR_W + 1;

    // ---------------------------------------------------------------
    // Memory
    // ---------------------------------------------------------------
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // ---------------------------------------------------------------
    // Write domain: binary and Gray write pointers
    // ---------------------------------------------------------------
    reg  [PTR_W-1:0] wbin;
    reg  [PTR_W-1:0] wgray;
    wire [PTR_W-1:0] wbin_next;
    wire [PTR_W-1:0] wgray_next;

    wire [ADDR_W-1:0] waddr = wbin[ADDR_W-1:0];
    wire              wgo   = winc & ~wfull;

    assign wbin_next  = wbin + {{(PTR_W-1){1'b0}}, wgo};
    assign wgray_next = (wbin_next >> 1) ^ wbin_next;

    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            wbin  <= {PTR_W{1'b0}};
            wgray <= {PTR_W{1'b0}};
        end else begin
            wbin  <= wbin_next;
            wgray <= wgray_next;
        end
    end

    // ---------------------------------------------------------------
    // Read domain: binary and Gray read pointers
    // ---------------------------------------------------------------
    reg  [PTR_W-1:0] rbin;
    reg  [PTR_W-1:0] rgray;
    wire [PTR_W-1:0] rbin_next;
    wire [PTR_W-1:0] rgray_next;

    wire [ADDR_W-1:0] raddr = rbin[ADDR_W-1:0];
    wire              rgo   = rinc & ~rempty;

    assign rbin_next  = rbin + {{(PTR_W-1){1'b0}}, rgo};
    assign rgray_next = (rbin_next >> 1) ^ rbin_next;

    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            rbin  <= {PTR_W{1'b0}};
            rgray <= {PTR_W{1'b0}};
        end else begin
            rbin  <= rbin_next;
            rgray <= rgray_next;
        end
    end

    // ---------------------------------------------------------------
    // Two-flop synchronisers for the crossing Gray pointers
    // ---------------------------------------------------------------
    // write Gray pointer -> read domain
    reg [PTR_W-1:0] wgray_sync1;
    reg [PTR_W-1:0] wgray_sync2;
    always @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            wgray_sync1 <= {PTR_W{1'b0}};
            wgray_sync2 <= {PTR_W{1'b0}};
        end else begin
            wgray_sync1 <= wgray;
            wgray_sync2 <= wgray_sync1;
        end
    end

    // read Gray pointer -> write domain
    reg [PTR_W-1:0] rgray_sync1;
    reg [PTR_W-1:0] rgray_sync2;
    always @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            rgray_sync1 <= {PTR_W{1'b0}};
            rgray_sync2 <= {PTR_W{1'b0}};
        end else begin
            rgray_sync1 <= rgray;
            rgray_sync2 <= rgray_sync1;
        end
    end

    // ---------------------------------------------------------------
    // Status flags, generated in their own clock domains
    // ---------------------------------------------------------------
    // Empty: next read Gray pointer equals the synced write Gray pointer
    assign rempty = (rgray_next == wgray_sync2);

    // Full: next write Gray pointer equals the synced read Gray pointer
    // with its two MSBs inverted (Gray wrap-around check)
    assign wfull = (wgray_next == {~rgray_sync2[PTR_W-1:PTR_W-2],
                                    rgray_sync2[PTR_W-3:0]});

    // ---------------------------------------------------------------
    // Data path
    // ---------------------------------------------------------------
    always @(posedge wclk) begin
        if (wgo)
            mem[waddr] <= wdata;
    end

    assign rdata = mem[raddr];

endmodule
